import java.util.Scanner;

public class Main {
    static final int MAXN = 510;
    static long[][] c = new long[MAXN][MAXN];
    static long[] f = new long[MAXN], g = new long[MAXN];
    static long[][] dp = new long[MAXN][MAXN], ways = new long[MAXN][MAXN];
    static long[][] dp2 = new long[MAXN][MAXN], ways2 = new long[MAXN][MAXN];
    static long[][] dp0 = new long[MAXN][MAXN], ways0 = new long[MAXN][MAXN];

    static long p;

    static void add_value(long[] x, int index, long y) {
        x[index] = (x[index] + y) % p;
    }

    static long calc_comb(long x) {
        return (x * (x - 1) / 2) % p;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        p = sc.nextLong();

        for (int i = 0; i < MAXN; i++) c[i][0] = 1;
        for (int i = 1; i < MAXN; i++) {
            for (int j = 1; j <= i; j++) {
                c[i][j] = (c[i - 1][j - 1] + c[i - 1][j]) % p;
            }
        }

        f[0] = 0;
        g[0] = 1;
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= i; j++) {
                long val1 = c[i - 1][j - 1] * f[j - 1] % p * g[i - j] % p * (i + 1) % p;
                long val2 = c[i - 1][j - 1] * g[j - 1] % p * f[i - j] % p * (i + 1) % p;
                add_value(f, i, (val1 + val2 + (c[i - 1][j - 1] * g[j - 1] % p * g[i - j] % p) * ((calc_comb(j) + calc_comb(i - j + 1)) % p) % p));
                add_value(g, i, c[i - 1][j - 1] * g[j - 1] % p * g[i - j] % p);
            }
        }

        for (int i = 0; i < MAXN; i++) {
            for (int j = 0; j < MAXN; j++) {
                dp[i][j] = 0;
                ways[i][j] = 0;
            }
        }
        dp[0][0] = 0;
        ways[0][0] = 1;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < MAXN; j++) {
                for (int k = 0; k < MAXN; k++) {
                    dp2[j][k] = 0;
                    ways2[j][k] = 0;
                }
            }

            for (int j = 0; j <= Math.min(i, m); j++) {
                for (int k = 0; k <= Math.min(j, m); k++) {
                    if (k == 0) {
                        dp0[i][j] = dp[j][0];
                        ways0[i][j] = ways[j][0];
                    }
                    add_value(dp2[j], k, dp[j][k]);
                    add_value(ways2[j], k, ways[j][k]);
                    int rem = m - (j - k);
                    if (j + 1 < MAXN && k + 1 < MAXN) {
                        add_value(ways2, j + 1, k + 1, ways0[i - k][j - k] * c[rem][k + 1] % p * g[k + 1] % p);
                        add_value(dp2, j + 1, k + 1, dp0[i - k][j - k] * c[rem][k + 1] % p * g[k + 1] % p + ways0[i - k][j - k] * c[rem][k + 1] % p * f[k + 1] % p);
                    }
                }
            }

            for (int j = 0; j < MAXN; j++) {
                for (int k = 0; k < MAXN; k++) {
                    dp[j][k] = dp2[j][k];
                    ways[j][k] = ways2[j][k];
                }
            }
        }

        long total = 0;
        for (int i = 0; i <= m; i++) {
            add_value(new long[]{total}, 0, dp[m][i]);
        }
        System.out.println(total);
        sc.close();
    }

    static void add_value(long[] array, int index, long y) {
        array[index] = (array[index] + y) % p;
    }

    static void add_value(long[][] array, int j, int k, long y) {
        array[j][k] = (array[j][k] + y) % p;
    }
}
